from hex_coordinates import catan_coordinate_system
from pathlib import Path

SCRIPT_DIR = Path(__file__).resolve().parent
LAYOUT_FILEPATH = SCRIPT_DIR.parent / "src" / "engine" / "system_layout.cpp"

auto_generation_warning = [
        "// WARNING: DO NOT EDIT FILE MANUALLY!!!\n",
        "// this file is generated by @scripts/build_static_layout_file.py\n",
        "// this file is only supposed to hold the static layout\n",
        "// implemented in @scripts/hex_coordinates.py\n",
]

include_statements = [
        "#include <array>\n",
        "#include <engine.h>\n",
]

# we will use the board.system to populate lines
# of the format f"\t{}"
array= ["\tstatic constexpr std::array<std::array<Marker, 21>, 21> system{{",
        "\t}};",]

function_body = [
        "using Marker = engine::BoardState::Marker;",
        "using Location = engine::BoardState::Location;",
        "const Marker renderLayout(Location loc){",
        "\treturn system[loc.q + 10][loc.r + 10];",
        "}",
]

def print_row(row: list[catan_coordinate_system.component]) -> str:
    # convert the list of components into the C++ entries
    entries = []
    for marker in row:
        entries.append(f'\n\t\t\tMarker::{marker.name}')

    return "\t\t{" + ",".join(entries) + "\n\t\t},"


# this file will write the layout to 
# src/engine/system_layout.cpp
def generate_layout_helper():
    board = catan_coordinate_system(layers=3)
    array_rows = []

    for row in board.array:        
        array_rows.append(print_row(row))

    # insert the entries into the function body
    array[1:1] = array_rows
    function_body[3:3] = array
    
    with open(LAYOUT_FILEPATH, 'w', encoding='utf-8') as layout_file:
        layout_file.writelines(auto_generation_warning)
        layout_file.writelines(include_statements)

        for line in range(len(function_body)):
            function_body[line] += '\n'
        layout_file.writelines(function_body)

if __name__ == "__main__":
    generate_layout_helper()
